"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["98946"],{21296(e){e.exports=JSON.parse('{"id":"F433","slug":"fx-forward-points","name":"Forward Exchange Rate and Forward Points","subject":"International Finance","section":"Global Finance","topic":"Spot and forward exchange rates","level":"Intermediate","aliases":["spot and forward exchange rates","forward premium","forward discount","swap points"],"formula":{"latex":"F=S\\\\,\\\\frac{1+r_{d}T/360}{1+r_{f}T/360},\\\\quad \\\\text{Points}=(F-S)\\\\times10{,}000","also":[],"text":"Forward rate = spot x (1 + domestic rate x days / 360) / (1 + foreign rate x days / 360), where rates are quoted as domestic currency per 1 unit of foreign currency; Forward points = (forward - spot) x 10,000; Annualized forward premium = (F / S - 1) x 360 / days"},"symbols":[{"symbol":"S","meaning":"Spot rate: units of domestic currency per 1 foreign currency","unit":"rate"},{"symbol":"r_d, r_f","meaning":"Domestic and foreign interest rates for the period","unit":"per year"},{"symbol":"T","meaning":"Days to the forward date","unit":"days"},{"symbol":"F","meaning":"Forward rate, set by the interest differential and not by a forecast","unit":"rate"}],"when_to_use":"Use it to price a forward exchange contract. The forward is set so that no one can profit from borrowing in one currency and lending in the other: the currency with the higher interest rate trades at a forward discount. Forward points are the quoted difference, added to the spot. The forward is not a prediction of the future spot rate. Day-count conventions vary by currency.","worked_example":{"problem":"EUR/USD spot is 1.0850 (USD per EUR). The 6-month USD rate is 5% and the EUR rate is 3%, with 180 days to the forward date.","inputs":{"s":1.085,"rd":5,"rf":3,"t":180},"steps":[{"label":"Forward rate","working":"1.085 x (1+0.05 x 180 / 360) / (1+0.03 x 180 / 360)","value":"1.09569"},{"label":"Forward points = (F - S) x 10,000","working":"(1.09569-1.085) x 10000","value":"106.9"},{"label":"Annualized forward premium = (F / S - 1) x 360 / days","working":"(1.09569 / 1.085-1) x 360 / 180","value":"1.97%"}],"answer":"The 180-day forward rate is 1.09569, which is 106.9 points above spot. The euro trades at a forward premium of 1.97% a year because USD interest rates are higher. Locking in the forward means a euro buyer pays 1.09569 for each euro at the forward date."},"calculator":{"available":true,"inputs":[{"id":"s","label":"Spot rate (USD per EUR)","unit":"","type":"number","default":1.085,"hint":""},{"id":"rd","label":"Domestic (USD) interest rate","unit":"%","type":"number","default":5,"hint":""},{"id":"rf","label":"Foreign (EUR) interest rate","unit":"%","type":"number","default":3,"hint":""},{"id":"t","label":"Days to the forward date","unit":"days","type":"number","default":180,"hint":"","min":1}],"checks":[{"expr":"s>0","message":"The spot rate must be above zero."}],"steps":[{"id":"f","label":"Forward rate","expr":"s*(1+rd*t/360)/(1+rf*t/360)","format":"num5"},{"id":"pts","label":"Forward points = (F - S) x 10,000","expr":"(f-s)*10000","format":"num1"},{"id":"prem","label":"Annualized forward premium = (F / S - 1) x 360 / days","expr":"(f/s-1)*360/t","format":"pct2"}],"results":["f","pts","prem"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"f":1.0956896551724138,"pts":106.89655172413825,"prem":1.9704433497536922e-2}},"finder":{"finds":"The forward rate and its premium or discount","needs":"Spot rate, both interest rates, days"},"related":[{"slug":"covered-interest-arbitrage","name":"Covered Interest Parity and Arbitrage"},{"slug":"fx-forward-hedge","name":"FX Forward Hedge and Covered Interest Parity"},{"slug":"money-market-hedge","name":"Hedging a Foreign Currency Receivable"}],"related_ids":["F434","F392","F441"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>F</mi><mo>=</mo><mi>S</mi><mtext>\u2009</mtext><mfrac><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>d</mi></msub><mi>T</mi><mi mathvariant=\\"normal\\">/</mi><mn>360</mn></mrow><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>f</mi></msub><mi>T</mi><mi mathvariant=\\"normal\\">/</mi><mn>360</mn></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Points</mtext><mo>=</mo><mo stretchy=\\"false\\">(</mo><mi>F</mi><mo>\u2212</mo><mi>S</mi><mo stretchy=\\"false\\">)</mo><mo>\xd7</mo><mn>10</mn><mo separator=\\"true\\" lspace=\\"0em\\" rspace=\\"0em\\">,</mo><mn>000</mn></mrow><annotation encoding=\\"application/x-tex\\">F=S\\\\,\\\\frac{1+r_{d}T/360}{1+r_{f}T/360},\\\\quad \\\\text{Points}=(F-S)\\\\times10{,}000</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"forward-contract-value","name":"Forward Contract: Fair Price, Value and Payoff"},"next":{"slug":"forward-rate","name":"Forward Rate from Spot Rates"},"lesson":null,"total":522}')}}]);